import{_ as a,o as t,c as o,l as i,t as s,N as r}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"docker-image-import | x-cmd man (docker man1) | Import the contents from a tarball to create a\\nfilesystem image","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-image-import - Import the contents from a tarball to create a\\nfilesystem image","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-image-import | x-cmd man (docker man1) | Import the contents from a tarball to create a\\nfilesystem image"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-image-import - Import the contents from a tarball to create a\\nfilesystem image"}]]},"headers":[],"params":{"isMan":true,"man":"docker-image-import","category":"docker man1","desc":"Import the contents from a tarball to create a\\nfilesystem image"},"relativePath":"docker/man1/docker-image-import.md","filePath":"docker/man1/docker-image-import.md"}'),l={name:"docker/man1/docker-image-import.md"},n={class:"visually-hidden"},p=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-image-import - Import the contents from a tarball to create a filesystem image</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker image import [OPTIONS] file|URL|- [REPOSITORY[:TAG]]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Create a new filesystem image from the contents of a tarball (<strong>.tar</strong>, <strong>.tar.gz</strong>, <strong>.tgz</strong>, <strong>.bzip</strong>, <strong>.tar.xz</strong>, <strong>.txz</strong>) into it, then optionally tag it.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="import-from-a-remote-location" tabindex="-1">Import from a remote location <a class="header-anchor" href="#import-from-a-remote-location" aria-label="Permalink to &quot;Import from a remote location&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker image import http://example.com/exampleimage.tgz example/imagerepo</span></span></code></pre></div><h2 id="import-from-a-local-file" tabindex="-1">Import from a local file <a class="header-anchor" href="#import-from-a-local-file" aria-label="Permalink to &quot;Import from a local file&quot;">​</a></h2><p>Import to docker via pipe and stdin:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cat exampleimage.tgz | docker image import - example/imagelocal</span></span></code></pre></div><p>Import with a commit message.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cat exampleimage.tgz | docker image import --message &quot;New image imported from tarball&quot; - exampleimagelocal:new</span></span></code></pre></div><p>Import to a Docker image from a local file.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker image import /path/to/exampleimage.tgz</span></span></code></pre></div><h2 id="import-from-a-local-file-and-tag" tabindex="-1">Import from a local file and tag <a class="header-anchor" href="#import-from-a-local-file-and-tag" aria-label="Permalink to &quot;Import from a local file and tag&quot;">​</a></h2><p>Import to docker via pipe and stdin:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cat exampleimageV2.tgz | docker image import - example/imagelocal:V-2.0</span></span></code></pre></div><h2 id="import-from-a-local-directory" tabindex="-1">Import from a local directory <a class="header-anchor" href="#import-from-a-local-directory" aria-label="Permalink to &quot;Import from a local directory&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tar -c . | docker image import - exampleimagedir</span></span></code></pre></div><h2 id="apply-specified-dockerfile-instructions-while-importing-the-image" tabindex="-1">Apply specified Dockerfile instructions while importing the image <a class="header-anchor" href="#apply-specified-dockerfile-instructions-while-importing-the-image" aria-label="Permalink to &quot;Apply specified Dockerfile instructions while importing the image&quot;">​</a></h2><p>This example sets the docker image ENV variable DEBUG to true by default.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tar -c . | docker image import -c=&quot;ENV DEBUG=true&quot; - exampleimagedir</span></span></code></pre></div><h2 id="when-the-daemon-supports-multiple-operating-systems" tabindex="-1">When the daemon supports multiple operating systems <a class="header-anchor" href="#when-the-daemon-supports-multiple-operating-systems" aria-label="Permalink to &quot;When the daemon supports multiple operating systems&quot;">​</a></h2><p>If the daemon supports multiple operating systems, and the image being imported does not match the default operating system, it may be necessary to add <strong>--platform</strong>. This would be necessary when importing a Linux image into a Windows daemon.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># docker image import --platform=linux .\\linuximage.tar</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><p><strong>docker-export(1)</strong> to export the contents of a filesystem as a tar archive to STDOUT.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-c</strong>, <strong>--change</strong>= Apply Dockerfile instruction to the created image</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for import</p><p><strong>-m</strong>, <strong>--message</strong>=&quot;&quot; Set commit message for imported image</p><p><strong>--platform</strong>=&quot;&quot; Set platform if server is multi-platform capable</p><h2 id="see-also-1" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also-1" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-image(1)</strong></p>',36);function m(e,c,h,d,g,u){return t(),o("div",null,[i("h1",n,s(e.$params.man),1),p])}const b=a(l,[["render",m]]);export{f as __pageData,b as default};
